/**
 * Swizzled from @docusaurus/theme-classic.
 *
 * The stock component also marks a navbar doc item active when the current doc
 * merely shares a sidebar with it. This site uses a single autogenerated
 * sidebar (`tutorialSidebar`) for every doc, so that check made EVERY dropdown
 * entry render as active on any docs page. Match on the doc path only.
 */
import React from 'react';
import {useActiveDocContext} from '@docusaurus/plugin-content-docs/client';
import {useLayoutDoc} from '@docusaurus/theme-common/internal';
import DefaultNavbarItem from '@theme/NavbarItem/DefaultNavbarItem';

export default function DocNavbarItem({
  docId,
  label: staticLabel,
  docsPluginId,
  ...props
}) {
  const {activeDoc} = useActiveDocContext(docsPluginId);
  const doc = useLayoutDoc(docId, docsPluginId);
  // Draft items are not displayed in the navbar.
  if (doc === null) {
    return null;
  }
  return (
    <DefaultNavbarItem
      exact
      {...props}
      isActive={() => activeDoc?.path === doc.path}
      label={staticLabel ?? doc.id}
      to={doc.path}
    />
  );
}
